'use client';

import { motion, useScroll, useTransform } from 'framer-motion';
import { useRef } from 'react';

export default function BackgroundKinetic() {
    const containerRef = useRef(null);
    const { scrollYProgress } = useScroll();

    const rotate = useTransform(scrollYProgress, [0, 1], [0, 360]);
    const scale = useTransform(scrollYProgress, [0, 0.5, 1], [1, 1.5, 1]);

    return (
        <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden bg-[#050505]">
            {/* Primary Royal Glow */}
            <motion.div
                style={{ rotate, scale }}
                className="absolute top-[-20%] left-[-10%] w-[120%] h-[120%] opacity-20"
            >
                <svg viewBox="0 0 1000 1000" xmlns="http://www.w3.org/2000/svg" className="w-full h-full">
                    <defs>
                        <radialGradient id="royalGrad" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
                            <stop offset="0%" stopColor="#800000" stopOpacity="0.8" />
                            <stop offset="100%" stopColor="#050505" stopOpacity="0" />
                        </radialGradient>
                    </defs>
                    <path
                        d="M500,200 Q700,100 800,400 T500,800 T200,400 T500,200"
                        fill="url(#royalGrad)"
                        className="animate-pulse"
                    />
                </svg>
            </motion.div>

            {/* Secondary Gold Glow */}
            <motion.div
                animate={{
                    x: [0, 50, 0],
                    y: [0, -30, 0],
                }}
                transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] bg-[#D4AF37] rounded-full filter blur-[150px] opacity-[0.05]"
            />

            {/* Noise Overlay */}
            <div className="absolute inset-0 opacity-[0.03] mix-blend-overlay pointer-events-none bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
        </div>
    );
}
