'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { ThemeToggle } from './ThemeToggle';

export default function Navbar() {
  const pathname = usePathname();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '/' },
    { name: 'About', href: '/about' },
    { name: 'Services', href: '/services' },
    { name: 'Contact', href: '/contact' },
  ];

  return (
    <div className="fixed bottom-0 inset-x-0 z-50">
      <nav className="bg-[#050505]/90 backdrop-blur-xl border-t border-white/5 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-8">
          <Link href="/" className="group flex items-center gap-2">
            <span className="text-xl font-black text-white tracking-tighter">SYNTAX<span className="text-[#800000]">WEB</span></span>
          </Link>

          <div className="hidden md:flex items-center gap-6 border-l border-white/10 pl-8 ml-2">
            {navLinks.map((link) => {
              const isActive = pathname === link.href;
              return (
                <Link
                  key={link.name}
                  href={link.href}
                  className={`text-[10px] font-black uppercase tracking-widest transition-all duration-300
                    ${isActive ? 'text-[#D4AF37]' : 'text-gray-500 hover:text-white'}`}
                >
                  {link.name}
                </Link>
              );
            })}
          </div>
        </div>

        <div className="flex items-center gap-6">
          <Link
            href="/admin/login"
            className="text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-white transition-colors"
          >
            Partners Login
          </Link>
          <Link
            href="/contact"
            className="px-6 py-3 bg-white text-black text-[10px] font-black uppercase tracking-widest rounded-none hover:bg-[#800000] hover:text-white transition-all duration-500"
          >
            Start a Project
          </Link>
        </div>
      </nav>
    </div>
  );
}

